<?php
use Illuminate\Http\Request;
use Illuminate\Support\Facades\Route;
use Shipping\{Settings,Ledger,Broker,Rules,Scenario,Validation,Conflict};
Route::get('/health/live',fn()=>['application'=>'shipping','alive'=>true]);
Route::get('/health/ready',function(Ledger $ledger,Settings $settings){try{$status=$ledger->status();$broker=Broker::ready($settings);$roles=array_column(array_filter($status['heartbeats'],fn($x)=>$x['healthy']),'role');$ready=$broker&&in_array('controller',$roles,true)&&in_array('worker',$roles,true)&&!in_array($status['run']['state'],['failed','stalled'],true);return response()->json(['application'=>'shipping','database'=>true,'broker'=>$broker,'ready'=>$ready],$ready?200:503);}catch(Throwable){return response()->json(['application'=>'shipping','ready'=>false],503);}});
Route::get('/status',function(Request $request,Ledger $ledger,Settings $settings){$value=$ledger->status();return ['identity'=>$request->attributes->get('shipping.identity'),'application'=>'shipping','providers'=>$settings->providers,'quantum'=>$settings->quantum,'simulation_time'=>(new Scenario($value['run']['scenario']))->instant($value['run']['granted'])->format('Y-m-d\TH:i:s.uP'),...$value];});
Route::post('/jobs',function(Request $request,Ledger $ledger){if(strlen($request->getContent())>65536)throw new Validation('Command too large');$job=Rules::job(Rules::object($request->getContent()));$key=$request->header('Idempotency-Key');if(!is_string($key)||strlen($key)<1||strlen($key)>128)throw new Validation('Idempotency-Key length must be 1..128');foreach(['synthetic:','boundary:','synthetic-sample:','shipping:'] as $prefix)if(str_starts_with($key,$prefix))throw new Conflict('This idempotency key namespace is reserved for internal providers');return $ledger->schedule($key,$job['due_at'],$job['quantity'],$request->attributes->get('shipping.audit'));});
Route::post('/control/{action}',function(Request $request,Ledger $ledger,string $action){if(strlen($request->getContent())>65536)throw new Validation('Command too large');$body=Rules::object($request->getContent());if(isset($body['scenario'])&&!is_array($body['scenario']))throw new Validation('Scenario object required');return $ledger->control($action,$body,$request->attributes->get('shipping.audit'));});
Route::get('/sources',fn()=>response()->json([]));Route::get('/audit',fn(Ledger $ledger)=>$ledger->auditEvents());
Route::get('/shipping',fn(Shipping\Fulfilment $shipping)=>$shipping->snapshot());
Route::get('/shipping/orders/{id}',fn(Shipping\Fulfilment $shipping,string $id)=>$shipping->order($id));
Route::post('/shipping/commands',function(Request $request,Shipping\Fulfilment $shipping){if(strlen($request->getContent())>65536)throw new Validation('Command too large');$key=$request->header('Idempotency-Key');if(!is_string($key))throw new Validation('Idempotency-Key required');return $shipping->submit($key,Rules::object($request->getContent()),$request->attributes->get('shipping.audit'));});
